const TEX = {};
(function buildTextures() {
  /* --- damp asphalt: albedo grain, normal map, wetness (roughness) --- */
  const S = 512, grain = fbmField(S, 64, 3, 0.6), blot = fbmField(S, 6, 4, 0.55), px = [0, 0, 0];
  const speck = new Float32Array(S * S);
  for (let i = 0; i < 5200; i++) speck[(rand() * S * S) | 0] = 0.35 + rand() * 0.65;
  TEX.asphalt = canvasTex(fieldToCanvas(S, (i) => {
    const g = 46 + (grain[i] - 0.5) * 44 + (blot[i] - 0.5) * 20 + speck[i] * 46;
    px[0] = g * 0.96; px[1] = g * 0.99; px[2] = g * 1.06; return px;
  }), true, true);
  TEX.asphaltN = canvasTex(fieldToCanvas(S, (i, x, y) => {
    const xl = grain[y * S + ((x + S - 1) % S)], xr = grain[y * S + ((x + 1) % S)], yu = grain[((y + S - 1) % S) * S + x], yd = grain[((y + 1) % S) * S + x];
    let nx = (xl - xr) * 2.2, ny = (yu - yd) * 2.2; const il = 1 / Math.sqrt(nx * nx + ny * ny + 1);
    px[0] = (nx * il * 0.5 + 0.5) * 255; px[1] = (ny * il * 0.5 + 0.5) * 255; px[2] = (il * 0.5 + 0.5) * 255; return px;
  }), false, true);
