  TEX.wet = canvasTex(fieldToCanvas(256, (i) => { const w = sstep(0.38, 0.62, wet[i]); const r = 255 * (0.30 + 0.70 * w); px[0] = r; px[1] = r; px[2] = r; return px; }), false, true);

  /* --- carbon-fibre twill weave --- */
  (function () {
