      gr.addColorStop(0, 'rgb(' + (a * 0.45 | 0) + ',' + (a * 0.47 | 0) + ',' + (a * 0.5 | 0) + ')');
      gr.addColorStop(0.5, 'rgb(' + a + ',' + (a + 2) + ',' + (a + 5) + ')');
      gr.addColorStop(1, 'rgb(' + (a * 0.45 | 0) + ',' + (a * 0.47 | 0) + ',' + (a * 0.5 | 0) + ')');
