    g.fillStyle = gr; g.fillRect(0, 0, 8, 256);
    g.fillStyle = 'rgba(255,255,255,0.05)';
    for (let y = 0; y < 256; y += 6) g.fillRect(0, y, 8, 1);
    g.fillStyle = band;
    g.fillRect(0, 256 * 0.085, 8, 256 * 0.055); g.fillRect(0, 256 * 0.86, 8, 256 * 0.055);
    g.fillStyle = 'rgba(0,0,0,0.55)'; g.fillRect(0, 256 * 0.108, 8, 2); g.fillRect(0, 256 * 0.883, 8, 2);
    const t = canvasTex(c, true, false); t.wrapS = THREE.RepeatWrapping; return t;
  });

  /* --- liveries (invented): u = along the part, v = around the section (0.5 = top centreline) --- */
  TEX.livery = [['#c8102e', '#f3f4f6', '#7a0518'], ['#1546c8', '#c9ced6', '#0a2470']].map((cols) => {
    const c = mkCanvas(1024, 256), g = c.getContext('2d');
    g.fillStyle = cols[0]; g.fillRect(0, 0, 1024, 256);
    g.fillStyle = cols[2];                                   // darker lower flanks
    g.fillRect(0, 0, 1024, 26); g.fillRect(0, 230, 1024, 26);
    g.fillStyle = cols[1];
    g.fillRect(0, 122, 1024, 12);                            // centre-line stripe
