/* ==========================================================================
   World: floodlight masts (data), baked light pools, road, kerbs, barriers,
   catch fencing, terrain
   ========================================================================== */
const world = new THREE.Group(); scene.add(world);

function wrapDelta(s, s0) { let d = (s - s0) % LAP; if (d > LAP / 2) d -= LAP; if (d < -LAP / 2) d += LAP; return d; }
function bay(s, s0, half, trans) { return 1 - sstep(half, half + trans, Math.abs(wrapDelta(s, s0))); }
/* barrier distance from the centreline: ~9 m, opening into run-off bays on the outside of three corners */
function barrierOff(side, s) {
  let b = 9;
  if (side < 0) b += 14.5 * bay(s, 400, 44, 34) + 7.5 * bay(s, 1300, 30, 26);
  else b += 15.5 * bay(s, 725, 34, 30);
  return b;
}

/* ---------- floodlight masts: 22 masts, 70.5 m apart, alternating sides, 30 m tall ---------- */
const N_MAST = 22, MAST_H = 30;
const MASTS = [];
(function () {
  const t = mkT();
  for (let k = 0; k < N_MAST; k++) {
    const s = 55 + k * LAP / N_MAST, side = k % 2 === 0 ? 1 : -1, off = side * (barrierOff(side, s) + 4.5);
    trackAt(s, t);
    const bx = t.x + t.nx * off, bz = t.z + t.nz * off, by = t.y - 0.4;
    const hx = bx - t.nx * side * 2.2, hz = bz - t.nz * side * 2.2, hy = t.y + MAST_H;
    let ax = t.x - hx, ay = t.y - hy, az = t.z - hz; const il = 1 / Math.sqrt(ax * ax + ay * ay + az * az);
    MASTS.push({ s: s, side: side, bx: bx, by: by, bz: bz, x: hx, y: hy, z: hz, ax: ax * il, ay: ay * il, az: az * il, cx: t.x, cy: t.y, cz: t.z, nx: t.nx, nz: t.nz, tx: t.tx, tz: t.tz });
  }
})();
/* warm local lamps (pit building, grandstand roof) — baked only */
const WARM_LAMPS = [];
for (let x = -50; x <= 130; x += 30) WARM_LAMPS.push({ x: x, y: 7.5, z: 21, r: 20, i: 1.0 });
for (let x = 5; x <= 110; x += 15) WARM_LAMPS.push({ x: x, y: 11.5, z: -17, r: 17, i: 1.25 });

const POOL_I0 = 3.3;
const _irr = [0, 0];
/* baked irradiance (cool, warm) at a world point with normal n; n = 0 → isotropic receiver */
function poolIrr(x, y, z, nx, ny, nz) {
  let e = 0, w = 0; const iso = nx === 0 && ny === 0 && nz === 0;
  for (let k = 0; k < N_MAST; k++) {
    const m = MASTS[k], lx = m.x - x, ly = m.y - y, lz = m.z - z, d2 = lx * lx + ly * ly + lz * lz;
    if (d2 > 16900) continue;
    const d = Math.sqrt(d2), cn = iso ? 0.55 : (lx * nx + ly * ny + lz * nz) / d; if (cn <= 0) continue;
    const sp = sstep(0.588, 0.961, -(lx * m.ax + ly * m.ay + lz * m.az) / d); if (sp <= 0) continue;
