    const m = WARM_LAMPS[k], lx = m.x - x, ly = m.y - y, lz = m.z - z, d2 = lx * lx + ly * ly + lz * lz;
    if (d2 > m.r * m.r * 6.25) continue;
    const d = Math.sqrt(d2), cn = iso ? 0.55 : Math.max(0.12, (lx * nx + ly * ny + lz * nz) / d);
