  for (let i = 0; i < p.count; i++) {
    const r = iso ? poolIrr(p.getX(i), p.getY(i), p.getZ(i), 0, 0, 0) : poolIrr(p.getX(i), p.getY(i), p.getZ(i), n.getX(i), n.getY(i), n.getZ(i));
