/* centreline pool brightness lookup (1 m steps) used to light spray / smoke particles */
const POOL_S = new Float32Array(Math.ceil(LAP) + 2);
(function () { const t = mkT(); for (let i = 0; i < POOL_S.length; i++) { trackAt(i, t); POOL_S[i] = poolIrr(t.x, t.y + 0.6, t.z, 0, 0, 0)[0] / (POOL_I0 * 0.26); } })();
