/* ---------- material patch: baked pools (+ wet-road lamp streaks for the asphalt) ---------- */
const N_STREAK = 8;
const streakU = { uLampPos: { value: [] }, uLampCol: { value: [] } };
for (let i = 0; i < N_STREAK; i++) { streakU.uLampPos.value.push(new THREE.Vector3(0, 30, 0)); streakU.uLampCol.value.push(new THREE.Vector3(0, 0, 0)); }
const DYN_ROAD = 0.42;                 // how much of the travelling spot lights the static scenery takes
function bakeLit(mat, road) {
  mat.onBeforeCompile = function (sh) {
    sh.vertexShader = sh.vertexShader.replace('#include <common>', '#include <common>\nattribute vec3 aPool;\nvarying vec3 vPool;')
      .replace('#include <begin_vertex>', '#include <begin_vertex>\nvPool = aPool;');
