      pars += 'uniform vec3 uLampPos[' + N_STREAK + '];\nuniform vec3 uLampCol[' + N_STREAK + '];\nvarying float vWetK;\n';
      sh.vertexShader = sh.vertexShader.replace('varying vec3 vPool;', 'varying vec3 vPool;\nvarying float vWetK;')
        .replace('vPool = aPool;', 'vPool = aPool; vWetK = 1.0;');
