        'float roughnessFactor = roughness;\n{ float w1 = texture2D( roughnessMap, vUv * 0.137 ).g; float w2 = texture2D( roughnessMap, vUv * 0.53 + vec2(0.31,0.17) ).g; float wv = clamp(w1 * 0.75 + w2 * 0.35, 0.0, 1.0); roughnessFactor *= mix(0.30, 1.0, wv); diffuseColor.rgb *= mix(0.62, 1.0, wv); }');
      extra += 'for (int i = 0; i < ' + N_STREAK + '; i++) {\n' +
        '  vec3 lv = (viewMatrix * vec4(uLampPos[i], 1.0)).xyz - geometry.position; float ld = length(lv); lv /= ld;\n' +
        '  float nl = clamp(dot(geometry.normal, lv), 0.0, 1.0);\n' +
        '  IncidentLight il; il.direction = lv; il.color = uLampCol[i] / (1.0 + ld * ld / 3600.0); il.visible = true;\n' +
        '  reflectedLight.directSpecular += il.color * nl * PI * min(vec3(60.0), BRDF_Specular_GGX(il, geometry.viewDir, geometry.normal, material.specularColor, material.specularRoughness));\n' +
