/* ---------- ribbon builder: sweeps a cross-section [d, h, u, break?, r, g, b] along the centreline ---------- */
function ribbonGeo(s0, s1, step, sect, vScale, withColor) {
  const n = Math.max(1, Math.round((s1 - s0) / step)), t = mkT();
