const MAT = {};
(function buildRoad() {
  /* asphalt: 14 m wide, rubbered-in racing line through vertex colour */
  MAT.road = bakeLit(new THREE.MeshStandardMaterial({ map: TEX.asphalt, normalMap: TEX.asphaltN, normalScale: new THREE.Vector2(0.5, 0.5), roughnessMap: TEX.wet, roughness: 0.66, metalness: 0, envMapIntensity: 0.5, vertexColors: true }), true);
  const DS = [-7, -6.2, -4.4, -2.4, -0.8, 0.8, 2.4, 4.4, 6.2, 7];
  const roadGeo = ribbonGeo(0, LAP, 1.5, () => DS.map((d) => { const c = 1.0 - 0.2 * Math.exp(-d * d / 7); return [d, 0, d / 6, 0, c, c, c]; }), 6, true);
