    this.aPos = new THREE.InstancedBufferAttribute(this.pos, 3).setUsage(THREE.DynamicDrawUsage);
    this.aSz = new THREE.InstancedBufferAttribute(this.sz, 3).setUsage(THREE.DynamicDrawUsage);
    this.aCol = new THREE.InstancedBufferAttribute(this.col, 4).setUsage(THREE.DynamicDrawUsage);
    g.setAttribute('iPos', this.aPos); g.setAttribute('iSz', this.aSz); g.setAttribute('iCol', this.aCol);
    if (this.stretch) { this.axis = new Float32Array(max * 3); this.aAxis = new THREE.InstancedBufferAttribute(this.axis, 3).setUsage(THREE.DynamicDrawUsage); g.setAttribute('iAxis', this.aAxis); }
    this.mat = new THREE.ShaderMaterial({
      uniforms: { map: { value: tex }, uOcc: { value: o.occ || 0 }, uFogD: { value: o.noFog ? 0 : scene.fog.density }, uNear: { value: new THREE.Vector2(o.near0 || 0.05, o.near1 || 0.3) } },
      defines: this.stretch ? { STRETCH: 1 } : {},
      vertexShader: [
        'attribute vec3 iPos; attribute vec3 iSz; attribute vec4 iCol;',
        '#ifdef STRETCH', 'attribute vec3 iAxis;', '#endif',
        'uniform float uFogD; uniform vec2 uNear; varying vec2 vUv; varying vec4 vCol; varying float vFade;',
        'void main(){',
        '  vec4 mv = viewMatrix * vec4(iPos, 1.0); vec2 c = position.xy; vec2 off;',
        '  #ifdef STRETCH',
        '    vec3 av = (viewMatrix * vec4(iAxis, 0.0)).xyz; float dl = length(av.xy); vec2 dir = dl > 1e-5 ? av.xy / dl : vec2(1.0, 0.0);',
        '    off = dir * c.x * (dl + iSz.x) + vec2(-dir.y, dir.x) * c.y * iSz.x;',
        '  #else',
        '    float cs = cos(iSz.z), sn = sin(iSz.z); off = vec2(c.x * cs - c.y * sn, c.x * sn + c.y * cs) * iSz.xy;',
