  const c = mkCanvas(256, 128), g = c.getContext('2d');
  g.clearRect(0, 0, 256, 128); g.filter = 'blur(9px)'; g.fillStyle = 'rgba(0,0,0,0.92)';
  g.beginPath(); g.moveTo(40, 34); g.lineTo(206, 30); g.quadraticCurveTo(232, 64, 206, 98); g.lineTo(40, 94); g.quadraticCurveTo(24, 64, 40, 34); g.fill();
  g.filter = 'none'; return canvasTex(c, false, false);
})();

function buildCar(ci) {
  const M = carMats(ci), root = new THREE.Group(), body = new THREE.Group(); root.add(body);
  const car = { ci: ci, root: root, body: body, M: M, wheels: [], nMesh: 0 };
  const add = (geo, mat, o) => {
    const m = new THREE.Mesh(geo, mat); o = o || {};
    m.castShadow = !o.noCast; m.receiveShadow = !o.noRecv;
