    if (o.rot) m.rotation.set(o.rot[0], o.rot[1], o.rot[2]);
    (o.parent || body).add(m); m.updateMatrix(); m.matrixAutoUpdate = false; car.nMesh++; return m;
  };
  const both = (geo, mat, o) => { add(geo, mat, o); add(mirrorZ(geo), mat, o); };
  const wingMats = (top) => [top, CM.carbon];

  /* ---- nose, monocoque, bib ---- */
  add(loftGeo([{ x: 2.885, y: 0.21, w: 0.02, h: 0.014 }, { x: 2.86, y: 0.213, w: 0.052, h: 0.033 }, { x: 2.78, y: 0.22, w: 0.078, h: 0.046 }, { x: 2.55, y: 0.25, w: 0.105, h: 0.068 },
