(function () { const t = trackAt(2, mkT()); for (let i = 0; i < 5; i++) for (const y of [4.82, 5.58]) { const z = (i - 2) * 1.16; START_LAMPS.push([t.x + t.tx * -0.86 + t.nx * z, t.y + y, t.z + t.tz * -0.86 + t.nz * z, i]); } })();

function drsOpen(c, t) { return c === 1 ? sstep(T_DRS_OPEN, T_DRS_OPEN + 0.14, t) * (1 - sstep(T_FINISH_B, T_FINISH_B + 0.16, t)) : 0; }
