      const fy = y * sc, y0 = Math.floor(fy), ty = fy - y0, sy = ty * ty * (3 - 2 * ty), ya = (y0 % n) * n, yb = ((y0 + 1) % n) * n;
      for (let x = 0; x < size; x++) {
        const fx = x * sc, x0 = Math.floor(fx), tx = fx - x0, sx = tx * tx * (3 - 2 * tx), xa = x0 % n, xb = (x0 + 1) % n;
        const a = g[ya + xa] + (g[ya + xb] - g[ya + xa]) * sx, b = g[yb + xa] + (g[yb + xb] - g[yb + xa]) * sx;
        out[y * size + x] += (a + (b - a) * sy) * amp;
