   ========================================================================== */
const AUDIO = (function () {
  const A = { ok: false, playing: false };
  let ctx = null;
  try { const AC = window.AudioContext || window.webkitAudioContext; ctx = new AC(); } catch (e) { return A; }
  A.ctx = ctx;
  const tryResume = () => { if (ctx.state !== 'running') { const p = ctx.resume(); if (p && p.catch) p.catch(() => {}); } };
  tryResume();
  const once = () => { tryResume(); window.removeEventListener('pointerdown', once, true); window.removeEventListener('keydown', once, true); };
  window.addEventListener('pointerdown', once, true); window.addEventListener('keydown', once, true);

  const arand = mulberry32(4242);                       // audio-only seeded randomness
  const SR = ctx.sampleRate;
  const bus = ctx.createGain(); bus.gain.value = 0.9;
  const master = ctx.createGain(); master.gain.value = 0;
  const comp = ctx.createDynamicsCompressor();
  comp.threshold.value = -16; comp.knee.value = 10; comp.ratio.value = 8; comp.attack.value = 0.004; comp.release.value = 0.18;
  const outTrim = ctx.createGain(); outTrim.gain.value = 0.8;
  bus.connect(master); master.connect(comp); comp.connect(outTrim); outTrim.connect(ctx.destination);

  /* --- seeded noise buffers --- */
  function mkBuf(sec, fn) { const n = Math.floor(SR * sec), b = ctx.createBuffer(1, n, SR), d = b.getChannelData(0); fn(d, n); return b; }
