#!/usr/bin/env python3
"""Minimal Chrome DevTools Protocol driver (stdlib only) for headless testing.

usage: cdp.py <script.json>
script.json: {"url":..., "width":1920, "height":1080, "steps":[ {"eval": "js"}, {"shot": "path.png"}, {"sleep": 1.0}, {"scrub": 12.5}, ... ]}
"""
import base64, json, os, socket, struct, subprocess, sys, time, urllib.request

CHROME_SHELL = os.path.expanduser('~/Library/Caches/ms-playwright/chromium_headless_shell-1254/chrome-headless-shell-mac-arm64/chrome-headless-shell')
CHROME_FULL = os.path.expanduser('~/Library/Caches/ms-playwright/chromium-1254/chrome-mac-arm64/Google Chrome for Testing.app/Contents/MacOS/Google Chrome for Testing')


class WS:
    def __init__(self, url):
        assert url.startswith('ws://')
        rest = url[5:]
        hostport, path = rest.split('/', 1)
        host, port = hostport.split(':')
        self.s = socket.create_connection((host, int(port)))
        key = base64.b64encode(os.urandom(16)).decode()
        req = ('GET /%s HTTP/1.1\r\nHost: %s\r\nUpgrade: websocket\r\nConnection: Upgrade\r\n'
               'Sec-WebSocket-Key: %s\r\nSec-WebSocket-Version: 13\r\n\r\n') % (path, hostport, key)
        self.s.sendall(req.encode())
        buf = b''
        while b'\r\n\r\n' not in buf:
            buf += self.s.recv(4096)
        if b' 101 ' not in buf.split(b'\r\n', 1)[0]:
            print('WS handshake failed:', buf[:300])
        self.buf = buf.split(b'\r\n\r\n', 1)[1]

    def send(self, text):
        data = text.encode()
        hdr = bytearray([0x81])
        n = len(data)
        if n < 126:
            hdr.append(0x80 | n)
        elif n < 65536:
            hdr.append(0x80 | 126); hdr += struct.pack('>H', n)
        else:
            hdr.append(0x80 | 127); hdr += struct.pack('>Q', n)
        mask = os.urandom(4)
        hdr += mask
        body = bytes(b ^ mask[i % 4] for i, b in enumerate(data))
        self.s.sendall(bytes(hdr) + body)

    def _read(self, n):
        while len(self.buf) < n:
            chunk = self.s.recv(1 << 20)
            if not chunk:
                raise EOFError('socket closed')
            self.buf += chunk
        out, self.buf = self.buf[:n], self.buf[n:]
        return out

    def recv(self):
        msg = b''
        while True:
            b0, b1 = self._read(2)
            fin, op = b0 & 0x80, b0 & 0x0f
            n = b1 & 0x7f
            if n == 126:
                n = struct.unpack('>H', self._read(2))[0]
            elif n == 127:
                n = struct.unpack('>Q', self._read(8))[0]
            payload = self._read(n)
            if op == 8:
                raise EOFError('ws closed')
            if op in (9, 10):
                continue
            msg += payload
            if fin:
                return msg.decode('utf-8', 'replace')


class CDP:
    def __init__(self, ws):
        self.ws = ws; self.id = 0; self.events = []

    def call(self, method, params=None, timeout=120):
        self.id += 1
        mid = self.id
        self.ws.send(json.dumps({'id': mid, 'method': method, 'params': params or {}}))
        self.ws.s.settimeout(timeout)
        while True:
            m = json.loads(self.ws.recv())
            if m.get('id') == mid:
                if 'error' in m:
                    raise RuntimeError(str(m['error']))
                return m.get('result', {})
            self.events.append(m)

    def ev(self, expr, await_promise=False):
        r = self.call('Runtime.evaluate', {'expression': expr, 'returnByValue': True, 'awaitPromise': await_promise})
        if 'exceptionDetails' in r:
            return {'EXC': r['exceptionDetails'].get('exception', {}).get('description', str(r['exceptionDetails']))}
        return r.get('result', {}).get('value')


def main():
    spec = json.load(open(sys.argv[1]))
    port = spec.get('port', 9333)
    w, h = spec.get('width', 1920), spec.get('height', 1080)
    exe = CHROME_FULL if spec.get('full') else CHROME_SHELL
    args = [exe, '--remote-debugging-port=%d' % port, '--window-size=%d,%d' % (w, h), '--hide-scrollbars', '--mute-audio',
            '--autoplay-policy=no-user-gesture-required', '--no-first-run', '--no-default-browser-check',
            '--user-data-dir=' + spec.get('profile', '/private/tmp/pcd-sbx-claude-fable-5.2-21vq3yqr/tmp/f1/profile'),
            '--allow-file-access-from-files', '--disable-background-timer-throttling', '--disable-renderer-backgrounding',
            '--remote-allow-origins=*']
    if spec.get('full'):
        args.append('--headless=new')
    args += spec.get('flags', ['--no-sandbox', '--disable-gpu-sandbox', '--use-angle=metal', '--enable-gpu', '--ignore-gpu-blocklist'])
    args.append('about:blank')
    proc = subprocess.Popen(args, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    try:
        info = None
        for _ in range(100):
            try:
                tabs = json.load(urllib.request.urlopen('http://127.0.0.1:%d/json' % port, timeout=1))
                pages = [t for t in tabs if t.get('type') == 'page']
                if pages:
                    info = pages[0]; break
            except Exception:
                time.sleep(0.1)
        if not info:
            print('no devtools endpoint'); return 1
        c = CDP(WS(info['webSocketDebuggerUrl']))
        c.call('Page.enable'); c.call('Runtime.enable'); c.call('Log.enable')
        c.call('Emulation.setDeviceMetricsOverride', {'width': w, 'height': h, 'deviceScaleFactor': spec.get('dpr', 1), 'mobile': False})
        c.call('Page.navigate', {'url': spec['url']})
        t0 = time.time()
        while time.time() - t0 < spec.get('loadTimeout', 60):
            if c.ev('document.readyState') == 'complete' and c.ev('typeof renderAt') == 'function':
                break
            time.sleep(0.25)
        for st in spec['steps']:
            if 'eval' in st:
                print('EVAL', st.get('label', st['eval'][:60]), '=>', json.dumps(c.ev(st['eval'], st.get('await', False)))[:spec.get('maxOut', 3000)])
            elif 'sleep' in st:
                time.sleep(st['sleep'])
            elif 'scrub' in st:
                c.ev("(function(){var s=document.getElementById('scrubber');s.value=%r;s.dispatchEvent(new Event('input'));})()" % st['scrub'])
            elif 'shot' in st:
                r = c.call('Page.captureScreenshot', {'format': st.get('format', 'png')})
                open(st['shot'], 'wb').write(base64.b64decode(r['data']))
                print('SHOT', st['shot'])
            elif 'click' in st:
                c.ev("document.querySelector(%r).click()" % st['click'])
        for m in c.events:
            meth = m.get('method', '')
            if meth == 'Runtime.exceptionThrown':
                d = m['params']['exceptionDetails']
                print('EXCEPTION', d.get('text'), d.get('exception', {}).get('description', '')[:1500], 'line', d.get('lineNumber'))
            elif meth == 'Runtime.consoleAPICalled':
                print('CONSOLE', m['params']['type'], ' '.join(str(a.get('value', a.get('description', ''))) for a in m['params']['args'])[:800])
            elif meth == 'Log.entryAdded':
                e = m['params']['entry']
                print('LOG', e.get('level'), e.get('text', '')[:800], e.get('url', '')[-60:], e.get('lineNumber'))
        return 0
    finally:
        proc.terminate()
        try:
            proc.wait(timeout=5)
        except Exception:
            proc.kill()


if __name__ == '__main__':
    sys.exit(main() or 0)

