  const a = carA(c, t), v = f.v, yr = yawRate(c, t), alat = v * yr;
  S.a = a; S.v = v; S.alat = alat;
  const pitch = clamp(a * 0.00038, -0.0085, 0.006), roll = clamp(-alat * 0.00034, -0.013, 0.013), q = sat(v / 70), heave = -0.007 * q * q;
  car.root.matrix.set(f.fx, f.ux, f.rx, f.px, f.fy, f.uy, f.ry, f.py, f.fz, f.uz, f.rz, f.pz, 0, 0, 0, 1);
