/* ---------- broadcast shot schedule: hard cuts, pure function of simTime ---------- */
const SHOT_T = [0, 5, 11, 15, 20, 24, 30, 34];
const SHOT_FOV = [35, 50, 24, 75, 28, 30, 30, 32];
