  const RATE = 240, LMAX = 1.5;
  for (let c = 0; c < 2; c++) {
    const T = TAB[c], i1 = Math.floor(t * RATE);
    for (let i = Math.max(0, Math.ceil((t - LMAX) * RATE) - 1); i <= i1; i++) {
